export async function load(dir: string) {
  const plugins: ConfigPluginV1.Spec[] = []

  for (const item of await Glob.scan("{plugin,plugins}/*.{ts,js}", {
    cwd: dir,
    absolute: true,
    dot: true,
    symlink: true,
  })) {
    plugins.push(pathToFileURL(item).href)
  }
  return plugins
}

execute(args, options) {
  return run.promise(
    Effect.gen(function* () {
      const ctx = context(args, options)
      yield* plugin.trigger(
        "tool.execute.before",
        { tool: item.id, sessionID: ctx.sessionID, callID: ctx.callID },
        { args },
      )
      const result = yield* item.execute(args, ctx)
      const output = {
        ...result,
        attachments: result.attachments?.map((attachment) => ({
          ...attachment,
          id: PartID.ascending(),
          sessionID: ctx.sessionID,
          messageID: input.processor.message.id,
        })),
      }
      yield* plugin.trigger(
        "tool.execute.after",
        { tool: item.id, sessionID: ctx.sessionID, callID: ctx.callID, args },
        output,
      )
      if (options.abortSignal?.aborted) {
        yield* input.processor.completeToolCall(options.toolCallId, output)
      }
      return output
    }),

const run = Effect.fn("ShellTool.run")(function* (
  input: {
    shell: string
    command: string
    cwd: string
    env: NodeJS.ProcessEnv
    timeout: number
  },
  ctx: Tool.Context,
) {
  const limits = yield* trunc.limits()
  const keep = limits.maxBytes * 2
  let full = ""

const code: number | null = yield* Effect.scoped(
  Effect.gen(function* () {
    yield* Effect.addFinalizer(closeSink)
    const handle = yield* spawner.spawn(cmd(input.shell, input.command, input.cwd, input.env))

    yield* Effect.forkScoped(
      Stream.runForEach(Stream.decodeText(handle.all), (chunk) => {
        const size = Buffer.byteLength(chunk, "utf-8")
        list.push({ text: chunk, size })
        used += size
        while (used > keep && list.length > 1) {
          const item = list.shift()
          if (!item) break
          used -= item.size
          cut = true
        }

        last = preview(last + chunk)

        if (file) {
          sink?.write(chunk)
        } else {
          full += chunk
          if (Buffer.byteLength(full, "utf-8") > limits.maxBytes) {
            return trunc.write(full).pipe(
              Effect.andThen((next) =>
                Effect.sync(() => {
                  file = next
                  cut = true
                  sink = createWriteStream(next, { flags: "a" })
                  full = ""
                }),
              ),

const meta: string[] = []
if (expired) {
  meta.push(
    `shell tool terminated command after exceeding timeout ${input.timeout} ms. If this command is expected to take longer and is not waiting for interactive input, retry with a larger timeout value in milliseconds.`,
  )
}
if (aborted) meta.push("User aborted the command")
const raw = list.map((item) => item.text).join("")
const end = tail(raw, limits.maxLines, limits.maxBytes)
if (end.cut) cut = true
if (!file && end.cut) {
  file = yield* trunc.write(raw)
}

let output = end.text
if (!output) output = "(no output)"

if (cut && file) {
  output = `...output truncated...\n\nFull output saved to: ${file}\n\n` + output
}

if (meta.length > 0) {
  output += "\n\n<shell_metadata>\n" + meta.join("\n") + "\n</shell_metadata>"
}
return {
  title: input.command,
  metadata: {
    output: last || preview(output),
    exit: code,
    truncated: cut,
    ...(cut && file ? { outputPath: file } : {}),
  },
  output,
}

const kinds = ["bash", "pwsh", "powershell", "cmd"] as const
export type Kind = (typeof kinds)[number]

const shellKinds = new Set<string>(kinds)

function isKind(value: string): value is Kind {
  return shellKinds.has(value)
}

export function toKind(value: string): Kind {
  return isKind(value) ? value : "bash"
}

// Keep the exposed tool ID and permission key as "bash" for compatibility with
// existing plugins, users, and saved permissions. Rename with opencode 2.0.
export const ToolID = "bash"
export type ToolID = typeof ToolID

export * as ShellID from "./id"

export const MAX_LINES = 2000
export const MAX_BYTES = 50 * 1024
export const DIR = TRUNCATION_DIR
export const GLOB = path.join(TRUNCATION_DIR, "*")

export type Result = { content: string; truncated: false } | { content: string; truncated: true; outputPath: string }

export interface Options {
  maxLines?: number
  maxBytes?: number
  direction?: "head" | "tail"

const limits = Effect.fn("Truncate.limits")(function* () {
  const configSvc = yield* Effect.serviceOption(Config.Service)
  if (Option.isNone(configSvc)) return { maxLines: MAX_LINES, maxBytes: MAX_BYTES }
  const cfg = yield* configSvc.value.get().pipe(Effect.catch(() => Effect.succeed(undefined)))
  return {
    maxLines: cfg?.tool_output?.max_lines ?? MAX_LINES,
    maxBytes: cfg?.tool_output?.max_bytes ?? MAX_BYTES,
  }
})

const output = Effect.fn("Truncate.output")(function* (text: string, options: Options = {}, agent?: Agent.Info) {
  const resolved = yield* limits()
  const maxLines = options.maxLines ?? resolved.maxLines
  const maxBytes = options.maxBytes ?? resolved.maxBytes
  const direction = options.direction ?? "head"
  const lines = text.split("\n")
  const totalBytes = Buffer.byteLength(text, "utf-8")

  if (lines.length <= maxLines && totalBytes <= maxBytes) {
    return { content: text, truncated: false } as const
  }
